//! External symbol library loader — typed port of the
//! `SKETCH_SYMBOL_LIBRARY` JSON shape (`assets/symbols.json`).
//!
//! The library stays EXTERNAL: it is loaded from disk at runtime, never
//! embedded with `include_str!`. `resolve` finds the file next to the
//! executable first (same dir, then `./assets/symbols.json`), then the cwd
//! variants. Deserialization is tolerant: missing fields fall back to
//! defaults and unknown fields are ignored, so a library generated by a
//! newer exporter still loads.

use std::collections::BTreeMap;
use std::fmt;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// Conventional file name of the external library.
pub const SYMBOL_LIBRARY_FILENAME: &str = "symbols.json";

/// Errors from [`SymbolLibrary::load`] and [`SymbolLibrary::load_resolved`].
#[derive(Debug)]
pub enum SymbolLibraryError {
    Io(std::io::Error),
    Json(serde_json::Error),
}

impl fmt::Display for SymbolLibraryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SymbolLibraryError::Io(e) => write!(f, "symbol library I/O: {e}"),
            SymbolLibraryError::Json(e) => write!(f, "symbol library JSON: {e}"),
        }
    }
}

impl std::error::Error for SymbolLibraryError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SymbolLibraryError::Io(e) => Some(e),
            SymbolLibraryError::Json(e) => Some(e),
        }
    }
}

impl From<std::io::Error> for SymbolLibraryError {
    fn from(e: std::io::Error) -> Self {
        SymbolLibraryError::Io(e)
    }
}

impl From<serde_json::Error> for SymbolLibraryError {
    fn from(e: serde_json::Error) -> Self {
        SymbolLibraryError::Json(e)
    }
}

/// Runtime resolution of the external library file. Looks, in order:
/// the caller's path hint, next to the executable (`symbols.json`, then
/// `assets/symbols.json`), then the same two under the current working
/// directory. Returns the first candidate that exists on disk; if none
/// exists, returns the conventional cwd `assets/symbols.json` so the error
/// `load` reports names the expected location.
pub fn resolve(path_hint: Option<&Path>) -> PathBuf {
    let mut candidates: Vec<PathBuf> = Vec::new();
    if let Some(hint) = path_hint {
        candidates.push(hint.to_path_buf());
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            candidates.push(dir.join(SYMBOL_LIBRARY_FILENAME));
            candidates.push(dir.join("assets").join(SYMBOL_LIBRARY_FILENAME));
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        candidates.push(cwd.join(SYMBOL_LIBRARY_FILENAME));
        candidates.push(cwd.join("assets").join(SYMBOL_LIBRARY_FILENAME));
    }
    for candidate in &candidates {
        if candidate.is_file() {
            return candidate.clone();
        }
    }
    candidates
        .pop()
        .unwrap_or_else(|| PathBuf::from("assets").join(SYMBOL_LIBRARY_FILENAME))
}

/// The whole `SKETCH_SYMBOL_LIBRARY` document.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct SymbolLibrary {
    pub version: u32,
    pub generated_from: String,
    pub symbol_count: usize,
    pub categories: Vec<SymbolCategory>,
    pub default_favorites: Vec<String>,
    /// Symbol id (`category/name`) to symbol definition.
    pub symbols: BTreeMap<String, Symbol>,
    /// Retired symbol id to the id that replaced it (left by merging
    /// duplicates), so sketches that placed the old id still find a symbol.
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub aliases: BTreeMap<String, String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct SymbolCategory {
    pub key: String,
    pub name: String,
    pub symbol_ids: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "UPPERCASE")]
pub enum WallSnap {
    #[default]
    None,
    Side,
    Center,
}

/// Sketch-space rectangle enclosing a symbol, in the symbol's units.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct Bounds {
    pub min_x: f64,
    pub min_y: f64,
    pub max_x: f64,
    pub max_y: f64,
}

/// Symbol units are inches; placed coordinates are feet, with rotation
/// clockwise on the screen. Return all corners for fitting and clipping.
pub fn world_corners(
    bounds: Bounds,
    x: f64,
    y: f64,
    rotation: f64,
    scale: f64,
    flip_h: bool,
) -> [crate::geometry::Pt; 4] {
    let (sin, cos) = rotation.to_radians().sin_cos();
    [
        (bounds.min_x, bounds.min_y),
        (bounds.max_x, bounds.min_y),
        (bounds.max_x, bounds.max_y),
        (bounds.min_x, bounds.max_y),
    ]
    .map(|(lx, ly)| {
        let lx = if flip_h { -lx } else { lx };
        crate::geometry::Pt::new(
            x + (lx * cos + ly * sin) * scale / 12.,
            y + (-lx * sin + ly * cos) * scale / 12.,
        )
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, Default)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

/// A polyline/arc vertex; `b` is the DXF-style bulge (arc sagitta) some
/// vertices carry.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, Default)]
pub struct Vertex {
    pub x: f64,
    pub y: f64,
    #[serde(default)]
    pub b: Option<f64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "UPPERCASE")]
pub enum EntityType {
    #[default]
    Line,
    Polyline,
    Arc,
    Ellipse,
    Text,
}

/// One geometry entity of a symbol. The exporter emits five entity kinds
/// (LINE, POLYLINE, ARC, ELLIPSE, TEXT) with kind-specific fields; a single
/// tolerant struct with optional fields mirrors that shape without
/// rejecting a library whose entities carry only the fields they need.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct Entity {
    /// Preview strokes for a native point; AXF output emits its real POINT.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub native_point: Option<bool>,
    pub entity_type: EntityType,
    /// Fill/ARGB-ish colour as exported (0 / 16777215 style integers).
    pub fill_color: Option<i64>,
    pub stroke_color: Option<i64>,
    pub stroke_alpha: Option<i64>,
    pub stroke_style: Option<String>,
    pub closed: Option<bool>,
    pub vertices: Option<Vec<Vertex>>,
    pub start_point: Option<Point>,
    pub end_point: Option<Point>,
    pub center: Option<Point>,
    pub axis_point: Option<Point>,
    pub ratio: Option<f64>,
    /// Angles are degrees in the exported library (e.g. 270).
    pub start_angle: Option<f64>,
    pub end_angle: Option<f64>,
    pub insert_point: Option<Point>,
    pub insertion_point: Option<Point>,
    pub rotation: Option<f64>,
    pub font_size: Option<f64>,
    pub alignment: Option<String>,
    pub text_string: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct Symbol {
    /// Independent native CAD records retained while placement is edited.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub native_apex: Option<serde_json::Value>,
    pub id: String,
    pub category: String,
    pub category_name: String,
    pub name: String,
    pub label: String,
    pub description: String,
    /// All exported symbols use `INCHES`; carried through verbatim.
    pub units: String,
    pub wall_snap: WallSnap,
    pub wall_gap_width: f64,
    pub wall_gap_alignment: f64,
    pub wall_cap_length: f64,
    pub bounds: Bounds,
    pub geometry: Vec<Entity>,
}

impl SymbolLibrary {
    /// Load the library from a JSON file on disk. The library stays
    /// external — never embedded — so it can be regenerated independently.
    pub fn load(path: &Path) -> Result<SymbolLibrary, SymbolLibraryError> {
        let text = std::fs::read_to_string(path)?;
        let library = serde_json::from_str(&text)?;
        Ok(library)
    }

    /// Resolve the library location at runtime ([`resolve`]) and load it.
    pub fn load_resolved(path_hint: Option<&Path>) -> Result<SymbolLibrary, SymbolLibraryError> {
        SymbolLibrary::load(&resolve(path_hint))
    }

    /// Look up one symbol by id (`category/name`).
    pub fn symbol(&self, id: &str) -> Option<&Symbol> {
        self.symbols.get(id)
    }

    /// Category index, in exported order.
    pub fn categories(&self) -> &[SymbolCategory] {
        &self.categories
    }

    /// The exporter's default favorite ids.
    pub fn favorites(&self) -> &[String] {
        &self.default_favorites
    }

    /// Groups of two or more symbols that draw and behave identically
    /// (same geometry, bounds and wall-snap settings). Each group lists the
    /// copy to keep first: not a `favorites/` copy, then the shortest id, then
    /// alphabetical. Groups are ordered by that first id. Symbols with no
    /// geometry are never grouped.
    pub fn duplicate_groups(&self) -> Vec<Vec<String>> {
        use std::hash::{Hash, Hasher};
        let mut by_shape: std::collections::HashMap<u64, Vec<&Symbol>> = Default::default();
        for symbol in self.symbols.values().filter(|s| !s.geometry.is_empty()) {
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            serde_json::to_string(&(
                &symbol.geometry,
                &symbol.bounds,
                &symbol.wall_snap,
                symbol.wall_gap_width.to_bits(),
                symbol.wall_gap_alignment.to_bits(),
                symbol.wall_cap_length.to_bits(),
            ))
            .unwrap_or_default()
            .hash(&mut hasher);
            by_shape.entry(hasher.finish()).or_default().push(symbol);
        }
        let mut groups: Vec<Vec<String>> = by_shape
            .into_values()
            .filter(|g| g.len() > 1 && g.iter().all(|s| s.geometry == g[0].geometry))
            .map(|g| {
                let mut ids: Vec<String> = g.iter().map(|s| s.id.clone()).collect();
                ids.sort_by_key(|id| (id.starts_with("favorites/"), id.len(), id.clone()));
                ids
            })
            .collect();
        groups.sort();
        groups
    }

    /// Number of symbols actually loaded.
    pub fn symbol_count(&self) -> usize {
        self.symbols.len()
    }
}

/* ── tests ──────────────────────────────────────────────────────── */

#[cfg(test)]
mod tests {
    use super::*;

    /// Path to the real exported library at the workspace root, if present.
    fn real_library_path() -> Option<PathBuf> {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let path = root.join("assets").join(SYMBOL_LIBRARY_FILENAME);
        path.is_file().then_some(path)
    }

    #[test]
    fn loads_real_library_with_expected_counts() {
        let Some(path) = real_library_path() else {
            eprintln!("skipping: assets/symbols.json not present");
            return;
        };
        let library = SymbolLibrary::load(&path).expect("library loads");
        assert_eq!(library.symbols.len(), 639);
        assert_eq!(library.symbol_count, 639);
        assert_eq!(library.categories.len(), 29);
        assert_eq!(library.default_favorites.len(), 18);
        assert_eq!(library.version, 1);
        assert_eq!(library.symbol_count(), 639);
    }

    #[test]
    fn accessors_and_geometry_shape_survive_the_real_library() {
        let Some(path) = real_library_path() else {
            eprintln!("skipping: assets/symbols.json not present");
            return;
        };
        let library = SymbolLibrary::load(&path).expect("library loads");

        let first_id = library
            .categories()
            .first()
            .and_then(|c| c.symbol_ids.first())
            .expect("at least one categorized symbol");
        let symbol = library.symbol(first_id).expect("category ids resolve");
        assert_eq!(symbol.id, *first_id);
        assert!(!symbol.geometry.is_empty());
        assert!(!symbol.label.is_empty());
        assert!(matches!(
            symbol.wall_snap,
            WallSnap::None | WallSnap::Side | WallSnap::Center
        ));
        assert_eq!(library.favorites().len(), 18);
    }

    #[test]
    fn resolve_prefers_existing_hint_and_never_panics() {
        if let Some(path) = real_library_path() {
            assert_eq!(resolve(Some(&path)), path);
            let library = SymbolLibrary::load_resolved(Some(&path)).expect("load_resolved");
            assert_eq!(library.symbols.len(), 639);
        }
        // With no file anywhere, resolution still returns a usable candidate path.
        let fallback = resolve(None);
        assert!(!fallback.as_os_str().is_empty());
    }

    #[test]
    fn tolerant_deserialization_ignores_unknown_fields_and_defaults_missing() {
        let json = r#"{
            "version": 1,
            "symbolCount": 1,
            "futureField": { "anything": true },
            "categories": [ { "key": "demo", "name": "Demo", "symbolIds": ["demo/box"], "extra": 7 } ],
            "defaultFavorites": ["demo/box"],
            "symbols": {
                "demo/box": {
                    "id": "demo/box",
                    "category": "demo",
                    "name": "Box",
                    "wallSnap": "CENTER",
                    "wallGapWidth": 36,
                    "bounds": { "minX": -2, "minY": -3, "maxX": 4, "maxY": 5, "extra": 1 },
                    "geometry": [
                        { "entityType": "LINE", "startPoint": { "x": 0, "y": 0 }, "endPoint": { "x": 1.5, "y": 2.5 }, "unknownEntityField": 9 },
                        { "entityType": "POLYLINE", "closed": true, "vertices": [ { "x": 0, "y": 0 }, { "x": 1, "y": 0, "b": 0.5 } ] },
                        { "entityType": "TEXT", "textString": "WH", "insertPoint": { "x": 0, "y": 0 }, "fontSize": 12 }
                    ]
                }
            }
        }"#;
        let library: SymbolLibrary = serde_json::from_str(json).expect("tolerant load");
        assert_eq!(library.symbols.len(), 1);
        let symbol = library.symbol("demo/box").expect("symbol");
        assert_eq!(symbol.wall_snap, WallSnap::Center);
        assert_eq!(symbol.wall_gap_width, 36.0);
        assert_eq!(symbol.bounds.max_x, 4.0);
        assert_eq!(symbol.geometry.len(), 3);
        assert_eq!(symbol.geometry[0].entity_type, EntityType::Line);
        assert_eq!(symbol.geometry[0].end_point.map(|p| p.x), Some(1.5));
        let vertices = symbol.geometry[1].vertices.as_ref().expect("vertices");
        assert_eq!(vertices[1].b, Some(0.5));
        assert_eq!(symbol.geometry[2].text_string.as_deref(), Some("WH"));
        // Fields the exporter always writes but the fixture omits default cleanly.
        assert_eq!(symbol.category_name, "");
        assert_eq!(library.favorites(), &["demo/box".to_owned()]);
    }

    #[test]
    fn load_reports_io_error_for_missing_file() {
        let err = SymbolLibrary::load(Path::new("definitely/not/here/symbols.json")).unwrap_err();
        assert!(matches!(err, SymbolLibraryError::Io(_)));
    }
}
